SELECT POPUP_ID, TITLE, START_YMD, END_YMD, LINK_URL, USE_YN, ATCH_FILE_GRPID, REGIST_DT FROM POPUP
AND TITLE LIKE '%' || #{searchKeyword} || '%'
AND USE_YN = #{useYn}
ORDER BY REGIST_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM POPUP
AND TITLE LIKE '%' || #{searchKeyword} || '%'
AND USE_YN = #{useYn}
